import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { parseDerExact, kids, integer, oid, readDer, seq, tlv, encodeUnsigned, u8 } from "./der";
import { mintTimeStampResponse, testTsaTrust } from "./__fixtures__/testTsa";
import { tsaProfile, trustFromProfile } from "./tsaProfiles";
import { parseInstantMicros } from "./time";
import { buildTimeStampRequest, extractToken, verifyTimeStampToken } from "./rfc3161";

// Test-only CA generated by tasks/artifacts/forge-pregame-capture-2026-11-14/tsa-fixture-gen/make-fixtures.sh.
const dir = join(__dirname, "__fixtures__", "tsa");
const read = (name: string) => readFileSync(join(dir, name));
const digest = createHash("sha256").update(u8(read("data.bin"))).digest();
const nonce = BigInt(read("nonce.txt").toString().trim());
const trust = { anchorsPem: [read("ca.crt").toString()], policies: ["1.3.6.1.4.1.99999.1"] };

describe("RFC 3161 verification", () => {
  it("verifies a pinned token and bounds its time by the stated accuracy", () => {
    const result = verifyTimeStampToken(extractToken(read("good.tsr")), { sha256Digest: digest, nonce }, trust);
    expect(result.accuracyMicros).toBe(BigInt(1_500_000));
    expect(result.accuracySource).toBe("token");
    // OpenSSL issues whole-second genTime: the bound adds the 1 s resolution as well as the 1.5 s accuracy.
    expect(result.resolutionMicros).toBe(BigInt(1_000_000));
    expect(result.upperMicros - result.genTimeMicros).toBe(BigInt(2_500_000));
    expect(result.genTimeMicros - result.lowerMicros).toBe(BigInt(2_500_000));
    expect(result.policy).toBe("1.3.6.1.4.1.99999.1");
    expect(result.nonce).toBe(nonce.toString());
  });

  it("refuses a different digest (hash or game-binding mismatch)", () => {
    const other = createHash("sha256").update("other-bytes").digest();
    expect(() => verifyTimeStampToken(extractToken(read("good.tsr")), { sha256Digest: other, nonce }, trust)).toThrow("tsa_imprint_mismatch");
  });

  it("refuses a replayed token with a different nonce", () => {
    expect(() => verifyTimeStampToken(extractToken(read("good.tsr")), { sha256Digest: digest, nonce: nonce + BigInt(1) }, trust)).toThrow("tsa_nonce_mismatch");
  });

  it("refuses a token that does not chain to a pinned anchor", () => {
    expect(() => verifyTimeStampToken(extractToken(read("good.tsr")), { sha256Digest: digest, nonce },
      { ...trust, anchorsPem: [read("other.crt").toString()] })).toThrow("tsa_chain_unanchored");
  });

  it("refuses an unpinned policy", () => {
    expect(() => verifyTimeStampToken(extractToken(read("good.tsr")), { sha256Digest: digest, nonce },
      { ...trust, policies: ["1.2.3"] })).toThrow("tsa_policy_not_pinned");
  });

  it("requires an accuracy bound unless the TSA policy pins one", () => {
    const token = extractToken(read("noacc.tsr"));
    expect(() => verifyTimeStampToken(token, { sha256Digest: digest, nonce }, trust)).toThrow("tsa_accuracy_missing");
    const pinned = verifyTimeStampToken(token, { sha256Digest: digest, nonce }, { ...trust, fallbackAccuracyMicros: BigInt(2_000_000) });
    expect(pinned).toMatchObject({ accuracySource: "pinned_policy", accuracyMicros: BigInt(2_000_000) });
  });

  it("refuses every single-bit flip anywhere in the token, including unsigned metadata and bundled certificates", () => {
    const token = extractToken(read("good.tsr"));
    const accepted: number[] = [];
    for (let offset = 0; offset < token.length; offset++) {
      const tampered = Buffer.from(u8(token));
      tampered[offset] ^= 0x01;
      try { verifyTimeStampToken(tampered, { sha256Digest: digest, nonce }, trust); accepted.push(offset); } catch { /* refused */ }
    }
    expect(accepted).toEqual([]);
  });

  it("builds a DER TimeStampReq for a SHA-256 digest with nonce and certReq", () => {
    const request = kids(parseDerExact(buildTimeStampRequest(digest, BigInt(42))), 0x30);
    expect(integer(request[0])).toBe(BigInt(1));
    expect(Buffer.from(u8(kids(request[1])[1].value)).equals(u8(digest))).toBe(true);
    expect(integer(request[2])).toBe(BigInt(42));
    expect(request[3].bytes.equals(u8(Buffer.from([0x01, 0x01, 0xff])))).toBe(true);
    expect(() => buildTimeStampRequest(Buffer.alloc(20), BigInt(1))).toThrow();
  });
});

describe("RFC 3161 refusals for malformed or mis-issued tokens", () => {
  const digest32 = Buffer.alloc(32, 7);
  const nonce7 = BigInt(77);
  const request = buildTimeStampRequest(digest32, nonce7);
  const at = parseInstantMicros("2026-11-20T22:00:00Z");
  const mint = (options: Partial<Parameters<typeof mintTimeStampResponse>[1]> = {}) =>
    extractToken(mintTimeStampResponse(request, { genTimeMicros: at, ...options }));
  const verify = (token: Buffer) => verifyTimeStampToken(token, { sha256Digest: digest32, nonce: nonce7 }, testTsaTrust());

  it("accepts the test signer's well-formed token and widens the bound by genTime's resolution", () => {
    // `at` is a whole second, so genTime carries no fraction: accuracy 0.5 s + resolution 1 s.
    expect(verify(mint()).upperMicros - at).toBe(BigInt(1_500_000));
    const fractional = verify(mint({ genTimeMicros: at + BigInt(250_000) }));
    expect(fractional.resolutionMicros).toBe(BigInt(10_000)); // ".25" → 10 ms
    expect(fractional.upperMicros - (at + BigInt(250_000))).toBe(BigInt(510_000));
  });

  it("accepts an off-path cross-signed anchor only by exact pinned SHA-256, and refuses any other stray certificate", () => {
    const pinCross = (token: Buffer) => verifyTimeStampToken(token, { sha256Digest: digest32, nonce: nonce7 },
      { ...testTsaTrust(), extraCertsSha256: ["bcefe97bba16b1447a9109385605036c6a170334938e1dcbf2b7c178284328fe"] });
    expect(() => pinCross(mint({ bundle: ["ca-cross.crt"] }))).not.toThrow();
    expect(() => verify(mint({ bundle: ["ca-cross.crt"] }))).toThrow("tsa_unexpected_certificate"); // not pinned
    expect(() => verify(mint({ bundle: ["ca.crt"] }))).not.toThrow(); // byte-identical anchor
    expect(() => pinCross(mint({ bundle: ["other.crt"] }))).toThrow("tsa_unexpected_certificate");
  });

  it("refuses a signer whose EKU is not critical, timestamping-only", () => {
    expect(() => verify(mint({ signer: "plain" }))).toThrow("tsa_signer_not_timestamping");
  });

  it("refuses a signer identifier that does not match the bound certificate", () => {
    expect(() => verify(mint({ sidSerial: BigInt(424242) }))).toThrow("tsa_signer_sid_mismatch");
  });

  it("refuses negative, zero or out-of-range accuracy parts", () => {
    const negativeSeconds = seq(tlv(0x02, Buffer.from([0xfb]))); // -5 s
    const zeroMillis = seq(tlv(0x80, Buffer.from([0x00])));
    const thousandMicros = seq(tlv(0x81, Buffer.from([0x03, 0xe8])));
    for (const rawAccuracy of [negativeSeconds, zeroMillis, thousandMicros]) {
      expect(() => verify(mint({ rawAccuracy }))).toThrow("tsa_accuracy_invalid");
    }
  });

  it("refuses GeneralizedTime values that Date.UTC would silently normalise", () => {
    for (const rawGenTime of ["20261320220000Z", "20261120240000Z", "00691120220000Z", "20261131220000Z"]) {
      expect(() => verify(mint({ rawGenTime }))).toThrow("der_generalized_time_range");
    }
  });

  it("refuses malformed DER integers and OIDs", () => {
    expect(() => integer(readDer(Buffer.from([0x02, 0x02, 0x00, 0x01])))).toThrow("der_integer_non_minimal");
    expect(() => integer(readDer(Buffer.from([0x02, 0x02, 0xff, 0x80])))).toThrow("der_integer_non_minimal");
    expect(() => integer(readDer(Buffer.from([0xa0, 0x03, 0x02, 0x01, 0x01])))).toThrow("der_not_integer");
    expect(() => oid(readDer(Buffer.from([0x06, 0x02, 0x2a, 0x86])))).toThrow("der_oid_truncated");
    expect(() => oid(readDer(Buffer.from([0x06, 0x03, 0x2a, 0x80, 0x01])))).toThrow("der_oid_non_minimal");
    expect(oid(readDer(Buffer.from([0x06, 0x0b, 0x2a, 0x86, 0x48, 0x86, 0xf7, 0x0d, 0x01, 0x09, 0x10, 0x01, 0x04])))).toBe("1.2.840.113549.1.9.16.1.4");
    expect(integer(readDer(encodeUnsigned(BigInt("123456789012345678901234567890"))))).toBe(BigInt("123456789012345678901234567890"));
  });

  it("refuses instants before the Unix epoch", () => {
    expect(() => parseInstantMicros("0069-11-20T22:00:00Z")).toThrow("instant_out_of_range");
  });
});

describe("DigiCert's real probe token (2026-11-15T02:37:45Z; random digest, no FHFH data)", () => {
  const tokenDer = extractToken(read("digicert-probe-20261115T023745Z.tsr"));
  const probe = JSON.parse(read("digicert-probe-20261115T023745Z.json").toString()) as { sha256Digest: string; nonce: string };
  const expectDigest = { sha256Digest: Buffer.from(probe.sha256Digest, "hex"), nonce: BigInt(probe.nonce) };
  const profile = tsaProfile("digicert-g4-v1");

  it("carries no Accuracy field: refused without a pinned fallback", () => {
    const { fallbackAccuracyMicros: _omit, ...withoutFallback } = trustFromProfile(profile, "probe");
    void _omit;
    expect(() => verifyTimeStampToken(tokenDer, expectDigest, withoutFallback)).toThrow("tsa_accuracy_missing");
  });

  it("verifies under the final capture profile: pinned policy, cross-signed root and the D3 60 s bound (+1 s resolution)", () => {
    const stamped = verifyTimeStampToken(tokenDer, expectDigest, trustFromProfile(profile, "capture"));
    expect(stamped).toMatchObject({ accuracySource: "pinned_policy", accuracyMicros: BigInt(60_000_000), resolutionMicros: BigInt(1_000_000) });
    expect(stamped.upperMicros - stamped.genTimeMicros).toBe(BigInt(61_000_000));
  });

  it("passes every other strict rule (illustrative fallback, not an approved value)", () => {
    const stamped = verifyTimeStampToken(tokenDer, expectDigest, { ...trustFromProfile(profile, "probe"), fallbackAccuracyMicros: BigInt(1) });
    expect(stamped).toMatchObject({ policy: "2.16.840.1.114412.7.1", accuracySource: "pinned_policy", genTime: "20261115023745Z" });
    expect(stamped.resolutionMicros).toBe(BigInt(1_000_000));
    expect(stamped.signerSha256).toBe("2da09da7f4131f9fe72db6c5e6e9c9656755af043f1ea742cc0d2120e141ebfc");
  });

  it("is refused for a different digest or nonce", () => {
    const trust = { ...trustFromProfile(profile, "probe"), fallbackAccuracyMicros: BigInt(1) };
    expect(() => verifyTimeStampToken(tokenDer, { ...expectDigest, sha256Digest: Buffer.alloc(32) }, trust)).toThrow("tsa_imprint_mismatch");
    expect(() => verifyTimeStampToken(tokenDer, { ...expectDigest, nonce: expectDigest.nonce + BigInt(1) }, trust)).toThrow("tsa_nonce_mismatch");
  });
});
